作者：D-████
本主题完全免费！
欢迎任意修改和使用~

@import url("https://fonts.googleapis.com/css2?family=Noto+Sans+SC:wght@400;500&display=swap");

body {
    font-family: "Noto Sans SC", sans-serif;
    font-weight: normal;
}

/* 基础消息气泡 */
#chat .mes_block {
    background: rgba(30, 10, 25, 0.9) !important;
    border-radius: 20px !important;
    border: 2px solid rgba(255, 180, 220, 0.5) !important;
    box-shadow: 0 4px 12px rgba(255, 100, 180, 0.2) !important;
}

/* ===添加音符闪烁效果=== */
@keyframes blinkNote {
 0%, 100% { opacity: 1; }
50% { opacity: 0.5; }
}

/* 添加原地旋转的六芒星动画效果*/
@keyframes spinHexagram {
  0% {
    transform: rotate(0deg);
    opacity: 1;  
  }
  100% {
    transform: rotate(360deg);
    opacity: 1;  
  }
}

/* 代码块 */
pre {
    background: rgba(225, 240, 255, 0.9) !important;
  color:rgba(0,0,0,0.9) !important;
  border: 2px solid rgba(255, 180, 220, 0.3) !important;
  overflow: hidden !important;
  border-radius: 16px !important;
}

/* 仅针对消息气泡的斜体文本气泡效果 */
#chat .mes_block em, #chat .mes_block i {
    display: inline-block;
    padding: 4px 12px;
        font-style: italic;
    color: rgba(255, 180, 220, 0.95);
}

#chat .mes_block em::before,#chat .mes_block i::before {
    content: "♪";
 animation: blinkNote 4s ease-in-out infinite;
   position: relative
    left: 0;
    opacity: 0.7;
}

/* 引用文本样式 */
q {
    display: inline-block;
    padding: 0 8px;
    color: rgba(209,181,226, 0.95) !important;
    border-left: 3px solid rgba(255, 120, 200, 0.7);
    background: rgba(80, 30, 70, 0.3) !important;
}

/* 标签页按钮样式 */
.inline-drawer-header,
#extensions_settings .inline-drawer-toggle.inline-drawer-header,
#extensions_settings2 .inline-drawer-toggle.inline-drawer-header,
#user-settings-block h4,
.standoutHeader {
  background: rgba(80, 20, 50, 0.95) !important;
}

/* 隐藏原生控件并设置基础样式 */
input[type="checkbox"], 
input[type="radio"] {
    appearance: none !important;
    -webkit-appearance: none !important;
    width: 16px !important;
    height: 16px !important;
    border: 2px solid rgba(255, 180, 220, 0.5) !important;
    background: rgba(60, 20, 50, 0.95) !important;
    cursor: pointer !important;
    position: relative !important;
    vertical-align: middle;
}

/* 复选框选中样式（粉色实心方块） */
input[type="checkbox"]:checked::after {
    content: "";
    position: absolute;
    width: 10px;
    height: 10px;
    background: rgba(255, 180, 220, 0.95) !important;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

/* 单选框样式（圆形） */
input[type="radio"] {
    border-radius: 50% !important;
}

/* 单选框选中样式（粉色实心圆点） */
input[type="radio"]:checked::after {
    content: "";
    position: absolute;
    width: 10px;
    height: 10px;
    background: rgba(255, 180, 220, 0.95) !important;
    border-radius: 50%;
    top: 50%;
    left: 50%;
    transform: translate(-50%, -50%);
}

/* 下拉选择框 */
select {
  background-color: rgba(60, 20, 50, 0.95) !important;
  border-color: rgba(60, 20, 50, 0.6) !important;
  color: rgba(255, 180, 220, 0.95) !important;
}

/* 输入框 */
input[type="text"],
input[type="number"],
textarea {
  background-color: rgba(60, 20, 50, 0.95) !important;
  border-color: rgba(60, 20, 50, 0.6) !important;
  color: rgba(255, 180, 220, 0.95) !important;
}

/* 极光闪烁动画 */
@keyframes auroraFlicker {
  0%, 100% { opacity: 0.8; }
  50% { opacity: 1; }
}

/* 用户头像雪花效果 */
.mes[is_user="true"] .avatar::before {
  content: "❄️";
  position: absolute;
  top: 4px;
  left: 0px;
  font-size: 20px;
  z-index: 10;
  animation: spinHexagram 8s linear infinite;
  pointer-events: none;
}

/* AI头像六芒星效果 */
.mes:not([is_user="true"]) .avatar::before {
  content: "✡";
  position: absolute;
  top: -2px;
  left: 4px;
  font-size: 30px;
  z-index: 10;
  animation: spinHexagram 8s linear infinite;
  pointer-events: none;
}

/* 消息气泡悬停特效 */
.mes_block:hover {
  transform: translateY(-2px);
  box-shadow: 0 6px 16px rgba(100, 210, 255, 0.25) !important;
  transition: all 0.3s ease;
}

/* 滚动条美化 */
::-webkit-scrollbar {
  width: 10px;
  background: rgba(230, 250, 255, 0.5);
}

::-webkit-scrollbar-thumb {
  background: linear-gradient(to bottom, rgba(100, 210, 255, 0.6), rgba(0, 200, 255, 0.4));
  border-radius: 20px;
  border: 3px solid rgba(230, 250, 255, 0.5);
}

/* 调整用户名 */
.mes .mes_name {
  margin-top: 10px; /* 用户名下移 */
  margin-left: 10px; /* 用户名右移 */
}

.mes .name_text {
  margin-top: 10px; /* 增加顶部边距，让名字往下移 */

}

.mes_text {
  width: 100% !important; /* 确保文本区域占满可用空间 */
  padding-right: 10px !important; /* 增加右侧内边距，避免文字太贴近边缘 */
}/* 可选的字体放大 */#chat .mes_text{
 font-size: 1.0em !important;
}/* 加入角色收藏栏划动功能 */
#HotSwapWrapper {
  overflow: hidden;
  overscroll-behavior-x: contain;
  scroll-snap-type: x mandatory;
}

#HotSwapWrapper > div,
#HotSwapWrapper .hotswap {
  overflow-x: auto !important;
  flex-wrap: nowrap !important;
  height: calc(var(--avatar-base-height) + var(--scroll-width) + 10px);
  max-height: calc(var(--avatar-base-height) * 2);
  scrollbar-width: none;
  -ms-overflow-style: none;
  -webkit-overflow-scrolling: touch;
}

body.big-avatars #HotSwapWrapper > div,
body.big-avatars #HotSwapWrapper .hotswap {
  height: calc(var(--avatar-base-height) * var(--big-avatar-height-factor) + var(--scroll-width) + 10px);
  max-height: calc(var(--avatar-base-height) * var(--big-avatar-height-factor) * 2);
}

#HotSwapWrapper > div::-webkit-scrollbar-thumb,
#HotSwapWrapper .hotswap::-webkit-scrollbar-thumb {
  background-color: var(--ui-color-sec);
}

#HotSwapWrapper > div:hover,
#HotSwapWrapper .hotswap:hover {
  scrollbar-width: thin;
}

#HotSwapWrapper > div::-webkit-scrollbar,
#HotSwapWrapper .hotswap::-webkit-scrollbar {
  display: none;
}
